如题，launch.json 如下：

```json
{
    "version": "0.2.0",
    "configurations": [
        {
            "name": "Debug backend",
            "type": "lldb",
            "request": "launch",
            "cargo": {
                "args": [
                    "build",
                    "--manifest-path",
                    "${workspaceFolder}/backend/Cargo.toml"
                ],
                "filter": {
                    "name": "backend",
                    "kind": "bin"
                }
            },
            "cwd": "${workspaceFolder}/backend",
            "env": {
                "RUST_BACKTRACE": "1"
            },
            "args": [],
            "sourceLanguages": [
                "rust"
            ]
        }
    ]
}
```

